const academyLessons=[
{id:'voice-advanced-01-mix',icon:'🎚️',title:['Mezcla vocal y transición de registros','Vocal mix and register transitions'],minutes:'20 min',objective:['Cruzar zonas de transición sin convertir cada nota alta en más volumen y presión.','Cross transition zones without turning every high note into more volume and pressure.'],concept:['La meta no es fabricar una voz nueva llamada mezcla. Es coordinar cambios de registro de forma progresiva ajustando intensidad, vocal y peso al subir.','The goal is not to manufacture a new voice called mix. It is to coordinate register changes progressively by adjusting intensity, vowel and weight as you ascend.'],feel:[['Sonido continuo y repetible sin fatiga inmediata.','A continuous sound that can be repeated without immediate fatigue.'],['Cuello y mandíbula sin aumento evidente de tensión.','Neck and jaw stay free from obvious extra tension.'],['Agudos algo más ligeros que los graves.','High notes feel somewhat lighter than low notes.']],avoid:[['Empujar el pecho hacia arriba.','Pushing chest voice upward.'],['Levantar la barbilla para alcanzar la nota.','Lifting the chin to reach the note.'],['Usar más volumen como única estrategia.','Using more volume as the only strategy.']],practice:[['Sirena suave con NG o Woo: 1–3–5–8–5–3–1 a 68–76 BPM.','Gentle NG or Woo siren: 1–3–5–8–5–3–1 at 68–76 BPM.'],['MUM: 1–2–3–4–5–4–3–2–1 a 78–86 BPM.','MUM: 1–2–3–4–5–4–3–2–1 at 78–86 BPM.'],['Pasa el patrón a una vocal de una canción real conservando la facilidad.','Move the pattern to a vowel from a real song while keeping the same ease.']],ministry:['Elige una frase del repertorio que suba hacia el coro. Cántala a volumen medio y luego con letra, sin aumentar presión al llegar arriba.','Choose a repertoire phrase that rises into the chorus. Sing it at medium volume and then with lyrics, without increasing pressure at the top.'],check:[['¿La nota alta salió más fácil al bajar un poco la intensidad?','Did the high note become easier when you reduced intensity slightly?'],['¿Pudiste repetir la frase tres veces sin endurecer cuello o mandíbula?','Could you repeat the phrase three times without tightening neck or jaw?']],target:{type:'category',id:'warm'}},
{id:'voice-advanced-02-passaggio',icon:'↗️',title:['Passaggio sin tensión','Passaggio without tension'],minutes:'18 min',objective:['Reconocer la zona donde la voz quiere reorganizarse y practicar alrededor de ella sin perseguir extremos.','Recognize where the voice wants to reorganize and practice around it without chasing extremes.'],concept:['El passaggio no se trabaja venciendo una nota problemática, sino coordinando varias notas alrededor de la transición hasta que deja de sentirse como una pared.','Passaggio is not trained by defeating one problem note, but by coordinating several notes around the transition until it stops feeling like a wall.'],feel:[['Transición gradual y posibilidad de hacer la nota más pequeña sin perder afinación.','A gradual transition and the ability to make the note smaller without losing pitch.'],['Libertad para volver inmediatamente a una nota media.','Freedom to return immediately to a middle note.']],avoid:[['Repetir muchas veces la nota que falla.','Repeating the failing note over and over.'],['Sostener agudos tensos para fortalecerlos.','Holding tense high notes to strengthen them.'],['Comparar tu rango con el de otro cantante.','Comparing your range with another singer.']],practice:[['NG-A en 1–2–3–2–1.','NG-A on 1–2–3–2–1.'],['NO o MUM en 1–3–5–3–1.','NO or MUM on 1–3–5–3–1.'],['Sube por semitonos solo mientras la repetición anterior siga cómoda.','Move by semitones only while the previous repetition remains comfortable.']],ministry:['Identifica una frase del setlist que cruce de zona media a alta. Practica primero la vocal dominante de la nota alta y luego devuelve la transición a la frase.','Identify a setlist phrase that crosses from middle to upper range. Practice the main vowel of the high note first, then return the transition to the phrase.'],check:[['¿Estoy intentando hacer la nota más grande o más fácil?','Am I trying to make the note bigger or easier?'],['¿Puedo detenerme antes de sentir fatiga?','Can I stop before fatigue appears?']],target:{type:'category',id:'resonance'}},
{id:'voice-advanced-03-dynamics',icon:'📈',title:['Control dinámico y volumen útil','Dynamic control and useful volume'],minutes:'18 min',objective:['Cantar suave, medio y firme sin que fuerte signifique gritar ni suave signifique perder afinación.','Sing softly, moderately and firmly without strong meaning shouting or soft meaning losing pitch.'],concept:['La dinámica crea contraste musical. El micrófono permite que el cantante no tenga que producir todo el volumen acústicamente.','Dynamics create musical contrast. A microphone means the singer does not need to produce all volume acoustically.'],feel:[['Afinación estable al cambiar intensidad.','Stable pitch while changing intensity.'],['Consonantes claras sin golpear.','Clear consonants without hammering.'],['El sonido crece sin endurecerse.','The sound grows without hardening.']],avoid:[['Competir con batería, guitarras o monitores.','Competing with drums, guitars or monitors.'],['Cantar todo al 100%.','Singing everything at 100%.'],['Confundir emoción con presión laríngea.','Confusing emotion with laryngeal pressure.']],practice:[['Cinco notas con MMM → MA, primero suave.','Five notes on MMM → MA, starting softly.'],['Repite a intensidad media sin cambiar afinación.','Repeat at medium intensity without changing pitch.'],['En una nota cómoda: suave → medio → firme → medio → suave.','On a comfortable note: soft → medium → firm → medium → soft.']],ministry:['Toma verso, pre-coro y coro. Planifica un crecimiento aproximado de 40–55%, 55–70% y 65–80% como referencias musicales, no físicas.','Take a verse, pre-chorus and chorus. Plan an approximate growth of 40–55%, 55–70% and 65–80% as musical, not physical, references.'],check:[['¿Mi afinación cambió al cantar más suave?','Did my pitch change when I sang more softly?'],['¿Subí intensidad sin levantar la barbilla?','Did I increase intensity without lifting my chin?']],target:{type:'category',id:'resonance'}},
{id:'voice-advanced-04-intervals',icon:'🎯',title:['Afinación avanzada e intervalos','Advanced pitch and intervals'],minutes:'20 min',objective:['Mejorar precisión en saltos, entradas difíciles y líneas que no siguen la melodía principal.','Improve accuracy in leaps, difficult entrances and lines that do not follow the main melody.'],concept:['Afinar no es solo dar la nota: hay que escuchar la referencia, anticipar la distancia y llegar sin arrastrarse desde otra nota.','Pitch accuracy is more than hitting the note: hear the reference, anticipate the distance and arrive without sliding from another note.'],feel:[['Entrada limpia y directa.','A clean, direct entrance.'],['Capacidad de imaginar la siguiente nota antes de cantarla.','Ability to imagine the next note before singing it.']],avoid:[['Deslizarte hasta encontrar la nota.','Sliding until you find the note.'],['Cantar más fuerte cuando no estás seguro.','Singing louder when unsure.'],['Depender visualmente del afinador durante toda la frase.','Watching the tuner through the whole phrase.']],practice:[['Eco de tres notas.','Three-note echo.'],['Arpegio mayor 1–3–5–8–5–3–1.','Major arpeggio 1–3–5–8–5–3–1.'],['Aísla 1→3, 1→5, 3→5 y 5→8; escucha el piano antes de cantar.','Isolate 1→3, 1→5, 3→5 and 5→8; hear the piano before singing.']],ministry:['Busca una entrada después de silencio o un salto grande. Practica solo las dos notas implicadas y después vuelve a la frase completa.','Find an entrance after silence or a large leap. Practice only the two involved notes, then return to the full phrase.'],check:[['¿Puedo oír mentalmente la siguiente nota antes de cantarla?','Can I hear the next note mentally before singing it?'],['¿Mi ataque llega directo o necesita corrección?','Does my attack arrive directly or need correction?']],target:{type:'category',id:'pitch'}},
{id:'voice-advanced-05-harmony',icon:'🎶',title:['Armonías para ministerios de alabanza','Harmony for worship ministries'],minutes:'25 min',objective:['Sostener una segunda voz sin regresar automáticamente a la melodía principal.','Hold a harmony part without automatically returning to the main melody.'],concept:['Una armonía útil pertenece al acorde y cumple una función dentro del arreglo. Para empezar, trabaja raíz, tercera y quinta de tríadas mayores.','A useful harmony belongs to the chord and serves a function in the arrangement. Start with root, third and fifth of major triads.'],feel:[['Escuchas el acorde completo además de tu propia voz.','You hear the whole chord as well as your own voice.'],['Puedes mantener una nota distinta mientras otro canta la melodía.','You can hold a different note while someone else sings the melody.']],avoid:[['Improvisar terceras paralelas durante toda la canción.','Improvising parallel thirds through the entire song.'],['Llenar cada frase con voces secundarias.','Filling every phrase with backing vocals.'],['Subir volumen cuando pierdes tu armonía.','Getting louder when you lose your harmony.']],practice:[['Piano toca 1–3–5; repite cada nota individual.','Piano plays 1–3–5; repeat each note individually.'],['Sostén la tercera mientras el piano repite la tríada.','Hold the third while the piano repeats the triad.'],['Alterna raíz y tercera sin deslizar.','Alternate root and third without sliding.']],ministry:['En un coro sencillo define por escrito dónde entra la armonía, dónde sale, qué queda al unísono y quién sostiene cada voz.','In a simple chorus, write down where harmony enters, exits, what stays in unison and who holds each part.'],check:[['¿Puedo mantener mi nota aunque otro cante la melodía?','Can I hold my note while someone else sings the melody?'],['¿Sé cuándo debo dejar de armonizar?','Do I know when to stop harmonizing?']],target:{type:'category',id:'pitch'}},
{id:'voice-advanced-06-endurance',icon:'⏳',title:['Resistencia vocal en ensayos y cultos','Vocal endurance in rehearsals and services'],minutes:'20 min',objective:['Administrar la voz en sesiones largas sin confundir resistencia con cantar fuerte por más tiempo.','Manage the voice through long sessions without confusing endurance with singing loudly for longer.'],concept:['La resistencia se construye con eficiencia, pausas, repertorio bien ubicado e intensidad sostenible; no aguantando dolor.','Endurance is built with efficiency, rests, smart repertoire placement and sustainable intensity; not by enduring pain.'],feel:[['Terminas el ensayo con una voz parecida a como empezaste.','You finish rehearsal with a voice similar to how you started.'],['Puedes alternar trabajo y descanso sin perder coordinación.','You can alternate work and rest without losing coordination.']],avoid:[['Cantar todas las canciones a máxima intensidad.','Singing every song at maximum intensity.'],['Competir con el monitoreo por volumen.','Competing with monitors for volume.'],['Continuar con dolor, ardor o ronquera que empeora.','Continuing through pain, burning or worsening hoarseness.']],practice:[['1 min respiración tranquila.','1 min relaxed breathing.'],['2 min trino de labios + 2 min humming.','2 min lip trills + 2 min humming.'],['2 min afinación media + 3 min frase real + 2 min humming descendente.','2 min middle-range pitch + 3 min real phrase + 2 min descending humming.']],ministry:['Antes revisa tonos y canciones exigentes; durante aprovecha partes instrumentales y otras voces; después baja intensidad y descansa si hubo mucha carga.','Beforehand review keys and demanding songs; during the service use instrumental sections and other voices; afterward reduce intensity and rest if the load was high.'],check:[['¿Las canciones difíciles están todas seguidas?','Are all the difficult songs back-to-back?'],['¿Puedo delegar líneas a otros cantantes?','Can I delegate lines to other singers?']],target:{type:'routine',id:'worship'}},
{id:'voice-advanced-07-agility',icon:'⚡',title:['Agilidad y melismas controlados','Agility and controlled melismas'],minutes:'18 min',objective:['Hacer adornos rápidos solo cuando mantienen ritmo, afinación y claridad.','Use fast ornaments only when rhythm, pitch and clarity remain intact.'],concept:['Un melisma útil debe poder cantarse lentamente y con notas identificables antes de acelerarlo.','A useful melisma should be singable slowly with identifiable notes before it is sped up.'],feel:[['Cada nota del adorno tiene lugar claro en el pulso.','Each ornament note has a clear place in the pulse.'],['La mandíbula no marca cada nota.','The jaw does not mark every note.']],avoid:[['Adornar cada final de frase.','Ornamenting every phrase ending.'],['Esconder desafinación detrás de velocidad.','Hiding poor pitch behind speed.'],['Copiar un melisma sin entender sus notas.','Copying a melisma without understanding its notes.']],practice:[['Cinco notas rápidas a 80 BPM.','Fast five-note pattern at 80 BPM.'],['Sube a 96 BPM solo después de tres repeticiones limpias.','Move to 96 BPM only after three clean repetitions.'],['Crea un adorno de 3–5 notas sobre una vocal y practícalo con pulso.','Create a 3–5 note ornament on one vowel and practice it in time.']],ministry:['Elige una sola frase donde el adorno tenga sentido y prepara también una versión simple para poder escoger según el contexto congregacional.','Choose one phrase where the ornament makes sense and also prepare a simple version so you can choose according to the congregational context.'],check:[['¿Puedo cantar el adorno a mitad de velocidad?','Can I sing the ornament at half speed?'],['¿El adorno sirve a la canción o solo demuestra habilidad?','Does the ornament serve the song or only show skill?']],target:{type:'category',id:'agility'}},
{id:'voice-advanced-08-setlist',icon:'📋',title:['Preparación vocal de un repertorio real','Preparing a real setlist vocally'],minutes:'25 min',objective:['Convertir las herramientas anteriores en una rutina concreta para preparar un setlist.','Turn the previous tools into a concrete routine for preparing a setlist.'],concept:['La preparación avanzada comienza antes de cantar: tono, frases exigentes, duración, armonías y distribución de carga deben revisarse como un conjunto.','Advanced preparation begins before singing: key, demanding phrases, duration, harmonies and workload distribution should be reviewed as a whole.'],feel:[['Sabes dónde están los puntos exigentes antes del ensayo.','You know where the demanding points are before rehearsal.'],['Puedes reservar energía para los momentos que realmente la necesitan.','You can save energy for the moments that truly need it.']],avoid:[['Descubrir en vivo que un tono queda demasiado alto.','Discovering live that a key is too high.'],['Practicar el set completo siempre a intensidad de escenario.','Always practicing the full set at stage intensity.'],['Dejar las armonías sin asignación previa.','Leaving harmonies unassigned.']],practice:[['Marca por canción: tono oficial, frase más exigente, canto continuo y armonías.','For each song mark: official key, hardest phrase, continuous singing and harmonies.'],['Calienta según lo que el set necesita, no por costumbre.','Warm up according to what the set requires, not by habit.'],['Ensaya las frases críticas primero aisladas y luego dentro del orden real.','Rehearse critical phrases first in isolation and then within the real order.']],ministry:['Ordena el set para distribuir demanda, define voces principales/secundarias y deja claro qué partes pueden descansar unos cantantes mientras otros sostienen la canción.','Order the set to distribute demand, assign lead/backing parts and make clear where some singers can rest while others carry the song.'],check:[['¿Sé cuál es la frase más exigente de cada canción?','Do I know the hardest phrase in each song?'],['¿El orden del set distribuye o acumula la carga?','Does the set order distribute or pile up vocal load?']],target:{type:'routine',id:'full'}}
];
