const ACADEMY_PROGRESS_KEY='lagrey_academy_voice_progress_v1';
function loadAcademyProgress(){try{const raw=JSON.parse(localStorage.getItem(ACADEMY_PROGRESS_KEY)||'{}');return{completed:Array.isArray(raw.completed)?raw.completed:[],lastOpened:raw.lastOpened||null}}catch{return{completed:[],lastOpened:null}}}
function saveAcademyProgress(data){localStorage.setItem(ACADEMY_PROGRESS_KEY,JSON.stringify({completed:[...new Set(data.completed||[])],lastOpened:data.lastOpened||null}))}
function academyIsComplete(id){return loadAcademyProgress().completed.includes(id)}
function academyProgressCount(){return academyLessons.filter(l=>academyIsComplete(l.id)).length}
function academyProgressHtml(){const done=academyProgressCount(),pct=Math.round(done/academyLessons.length*100);return `<div class="academy-progress-card"><div class="academy-progress-copy"><b>${vtx('Tu progreso','Your progress')}</b><span>${done}/${academyLessons.length} ${vtx('clases completadas','lessons completed')}</span></div><div class="academy-progress-track"><span style="width:${pct}%"></span></div><strong>${pct}%</strong></div>`}
function rememberAcademyOpen(id){const p=loadAcademyProgress();p.lastOpened=id;saveAcademyProgress(p)}
function toggleAcademyComplete(id){const p=loadAcademyProgress(),set=new Set(p.completed);if(set.has(id))set.delete(id);else set.add(id);p.completed=[...set];p.lastOpened=id;saveAcademyProgress(p);translateVoiceShell();renderAcademyLesson(id,false)}
let ctx=null,stopToken=0,routineState=null,activeVoicePanel=null,academySceneTimer=0;
function translatedExercise(cat,i,e=exercises[cat]?.[i]){if(!e||voiceLang()!=='en')return e;const t=exerciseEN[cat]?.[i];return t?{...e,name:t[0],tip:t[1],why:t[2],example:t[3]}:e}
function categoryText(id){const c=categories.find(x=>x.id===id),t=shellCategories[id],en=voiceLang()==='en';return c&&t?{...c,title:t[en?1:0],desc:t[en?3:2]}:c}
function routineTitle(id){const pair=shellRoutines[id];return pair?pair[voiceLang()==='en'?1:0]:routines[id]?.title||''}
function localText(pair){return Array.isArray(pair)?pair[voiceLang()==='en'?1:0]:pair||''}
function academyLesson(id){return academyLessons.find(x=>x.id===id)}
function academyList(items){return `<ul>${(items||[]).map(x=>`<li>${localText(x)}</li>`).join('')}</ul>`}
function academyCardHtml(l,i){const done=academyIsComplete(l.id);return `<button class="voice-academy-card${done?' completed':''}" data-academy-lesson="${l.id}"><span class="voice-academy-number">${done?'✓':String(i+1).padStart(2,'0')}</span><span class="voice-academy-icon">${l.icon}</span><b>${localText(l.title)}</b><small>${localText(l.objective)}</small><em>${done?vtx('Completada','Completed'):l.minutes}</em></button>`}
function academyInteractiveHtml(id){const drills=academyInteractive[id];if(!drills?.length)return'';return `<section class="voice-academy-interactive"><h3>🎹 ${vtx('Práctica interactiva','Interactive practice')}</h3><p>${vtx('El piano toca primero y luego te deja espacio para repetir. Empieza en una nota cómoda y detente antes de sentir presión.','The piano plays first, then leaves space for you to repeat. Start on a comfortable note and stop before you feel pressure.')}</p><div class="voice-exercise-list">${drills.map((d,i)=>`<article class="voice-exercise voice-academy-drill"><h3>${localText(d.name)}</h3><div class="voice-pattern">${d.pattern.map(degreeLabel).join(' – ')}</div><p>${localText(d.tip)}</p><div class="voice-controls"><label>${vtx('Sílaba','Syllable')}<select data-ap-syllable>${d.syllables.map(s=>`<option>${s}</option>`).join('')}</select></label><label>${vtx('Nota inicial','Starting note')}<select data-ap-start><option value="48">C3 · Do3</option><option value="50">D3 · Re3</option><option value="52">E3 · Mi3</option><option value="53">F3 · Fa3</option><option value="55">G3 · Sol3</option><option value="57">A3 · La3</option><option value="60" selected>C4 · Do4</option></select></label><label>Tempo<input data-ap-tempo type="range" min="60" max="100" value="${d.tempo}"><span data-ap-tempo-label>${d.tempo} BPM</span></label><label>${vtx('Repeticiones','Repetitions')}<select data-ap-repeats><option>1</option><option selected>3</option><option>5</option></select></label><label>${vtx('Movimiento','Movement')}<select data-ap-shift><option value="0">${vtx('No mover','Do not move')}</option><option value="1" selected>+½ ${vtx('tono','step')}</option><option value="-1">−½ ${vtx('tono','step')}</option></select></label></div><div class="voice-play-row"><button class="btn primary" data-academy-play="${id}|${i}">▶ ${vtx('Escuchar y practicar','Listen and practice')}</button><button class="btn" data-academy-demo="${id}|${i}">🎹 ${vtx('Solo ejemplo','Example only')}</button><button class="btn" data-academy-stop>■ ${vtx('Detener','Stop')}</button></div><div class="voice-status" data-academy-status>${vtx('Listo. El piano tocará el patrón y después tendrás espacio para repetirlo.','Ready. The piano will play the pattern, then leave space for you to repeat it.')}</div></article>`).join('')}</div></section>`}
function academyVideoHtml(id){const v=academyVideos[id];if(!v)return'';const eager=id==='voice-advanced-02-passaggio',preload=eager?'auto':'metadata',poster=eager?' poster="./academy-videos/passaggio/scene-01.svg"':'';return `<section class="voice-academy-video"><div class="voice-academy-video-head"><div><span class="voice-badge">🎬 ${vtx('Video de la clase','Lesson video')}</span><h3>${localText(v.title)}</h3></div><span class="voice-academy-duration">${v.duration}</span></div><p>${vtx('El video se reproduce aquí mismo dentro de la clase. Puedes verlo en línea o cambiarlo a pantalla completa.','The video plays right here inside the lesson. You can watch it inline or switch to full screen.')}</p><div class="academy-video-player${eager?' has-video academy-video-eager':''}" data-academy-video-box="${id}"><video controls playsinline preload="${preload}"${poster} data-academy-video="${id}"><source src="${v.src}" type="video/mp4"></video><div class="academy-video-fallback"><div class="academy-video-icon">🎥</div><b>${vtx('Video todavía no disponible','Video not available yet')}</b><small>${vtx('Esta clase conservará su guía visual hasta que tenga su video final.','This lesson keeps its visual guide until its final video is available.')}</small><button class="btn primary" data-academy-story="${id}">▶ ${vtx('Ver guía audiovisual','View audiovisual guide')}</button></div></div><div class="academy-video-actions${eager?'':' hidden'}" data-academy-video-actions="${id}"><button class="btn" type="button" data-academy-fullscreen="${id}">⛶ ${vtx('Pantalla completa','Full screen')}</button></div><div class="academy-story hidden" data-academy-story-box="${id}"><div class="academy-story-progress"><span data-academy-story-progress></span></div><div class="academy-story-count" data-academy-story-count></div><div class="academy-story-scene" data-academy-story-scene></div><div class="voice-play-row"><button class="btn" data-story-prev="${id}">← ${vtx('Anterior','Previous')}</button><button class="btn primary" data-story-play="${id}">▶ ${vtx('Reproducir','Play')}</button><button class="btn" data-story-next="${id}">${vtx('Siguiente','Next')} →</button></div></div></section>`}
function shellTitle(el,value){if(!el)return;const icon=el.querySelector('.lg-section-icon');if(icon){const label=[...el.children].find(n=>n!==icon);if(label)label.textContent=value;else el.append(document.createTextNode(value));return}el.textContent=`🎤 ${value}`}
function translateVoiceShell(){const v=$('#voiceView');if(!v)return;const en=voiceLang()==='en';const back=v.querySelector('[data-voice-home]');if(back)back.textContent=vtx('← Volver','← Back');shellTitle(v.querySelector('.voice-hero h1'),vtx('Voz','Voice'));const hero=v.querySelector('.voice-hero p');if(hero)hero.textContent=vtx('Rutinas guiadas, ejemplos, sílabas variadas y patrones de piano.','Guided routines, examples, varied syllables and piano patterns.');const warning=v.querySelector(':scope > .voice-warning');if(warning)warning.innerHTML=en?'<b>Take care of your voice:</b> work in a comfortable range, without pain or pressure. If pain, significant voice loss or persistent discomfort appears, stop the exercise.':'<b>Cuida tu voz:</b> trabaja en una zona cómoda, sin dolor ni presión. Si aparece dolor, pérdida marcada de voz o molestia persistente, detén el ejercicio.';const headings=v.querySelectorAll(':scope > h2');if(headings[0])headings[0].textContent=vtx('Rutinas guiadas','Guided routines');if(headings[1])headings[1].textContent=vtx('Entrena por objetivo','Train by goal');const at=v.querySelector('[data-academy-title]'),ai=v.querySelector('[data-academy-intro]');if(at)at.textContent=vtx('🎓 Academia La Grey · Voz avanzada','🎓 La Grey Academy · Advanced voice');if(ai)ai.textContent=vtx('8 clases para llevar la técnica vocal al ensayo, el culto, las armonías y el repertorio real.','8 lessons that bring vocal technique into rehearsals, services, harmony and real repertoire.');const prog=v.querySelector('[data-academy-progress]');if(prog)prog.innerHTML=academyProgressHtml();const grid=v.querySelector('[data-academy-grid]');if(grid)grid.innerHTML=academyLessons.map(academyCardHtml).join('');Object.entries(shellRoutines).forEach(([id,pair])=>{const b=v.querySelector(`[data-routine="${id}"]`);if(!b)return;const title=b.querySelector('b'),small=b.querySelector('small');if(title)title.textContent=pair[en?1:0];if(small)small.textContent=vtx('La Grey te lleva paso a paso y toca los ejercicios en orden.','La Grey guides you step by step and plays the exercises in order.')});Object.entries(shellCategories).forEach(([id,t])=>{const b=v.querySelector(`[data-voice-cat="${id}"]`);if(!b)return;const title=b.querySelector('b'),small=b.querySelector('small');if(title)title.textContent=t[en?1:0];if(small)small.textContent=t[en?3:2]})}
function injectStyle(){if($('#voiceCss'))return;const l=document.createElement('link');l.id='voiceCss';l.rel='stylesheet';l.href='voice.css';document.head.appendChild(l)}
function build(){injectStyle();const homeGrid=$('#home .home-grid');if(homeGrid&&!homeGrid.querySelector('[data-open="voice"]')){const b=document.createElement('button');b.className='card';b.dataset.open='voice';b.innerHTML=`<div class="icon">🎤✨</div><h2>${vtx('Voz','Voice')}</h2><div class="muted">${vtx('Calentamiento y entrenamiento vocal','Warm-ups and vocal training')}</div><div class="count">${vtx('Rutinas guiadas + piano','Guided routines + piano')}</div>`;homeGrid.appendChild(b)}if($('#voiceView')){translateVoiceShell();return}const s=document.createElement('section');s.id='voiceView';s.className='view hidden';s.innerHTML=`<button class="back" data-voice-home>← Volver</button><div class="voice-hero"><h1>🎤 Voz</h1><p>Rutinas guiadas, ejemplos, sílabas variadas y patrones de piano.</p></div><div class="voice-warning"><b>Cuida tu voz:</b> trabaja en una zona cómoda, sin dolor ni presión. Si aparece dolor, pérdida marcada de voz o molestia persistente, detén el ejercicio.</div><h2>Rutinas guiadas</h2><div class="voice-routines">${Object.entries(routines).map(([id,r])=>`<button class="voice-routine" data-routine="${id}"><b>${r.title}</b><br><small>La Grey te lleva paso a paso y toca los ejercicios en orden.</small></button>`).join('')}</div><h2>Entrena por objetivo</h2><div class="voice-grid">${categories.map(c=>`<button class="voice-card" data-voice-cat="${c.id}"><span class="voice-icon">${c.icon}</span><b>${c.title}</b><small>${c.desc}</small></button>`).join('')}</div><h2 data-academy-title>🎓 Academia La Grey · Voz avanzada</h2><p class="voice-academy-intro" data-academy-intro>8 clases para llevar la técnica vocal al ensayo, el culto, las armonías y el repertorio real.</p><div data-academy-progress>${academyProgressHtml()}</div><div class="voice-academy-grid" data-academy-grid>${academyLessons.map(academyCardHtml).join('')}</div><div id="voicePanel" class="voice-panel hidden"></div>`;document.querySelector('main').appendChild(s);translateVoiceShell()}
function showVoice(){build();translateVoiceShell();$$('.view').forEach(v=>v.classList.add('hidden'));$('#voiceView').classList.remove('hidden');$$('nav button').forEach(b=>b.classList.remove('active'));window.scrollTo(0,0)}
function goHome(){stopPlayback();$('#voiceView')?.classList.add('hidden');$('#home')?.classList.remove('hidden');window.scrollTo(0,0)}
function degreeLabel(n){const map={0:'1',2:'2',4:'3',5:'4',7:'5',9:'6',11:'7',12:'8',16:'10'};return map[n]||'•'}
function exerciseHtml(cat,i,source){const e=translatedExercise(cat,i,source);if(e.timed)return `<article class="voice-exercise"><h3>${e.name}</h3><p><b>${vtx('Para qué sirve:','What it does:')}</b> ${e.why}</p><p><b>${vtx('Cómo hacerlo:','How to do it:')}</b> ${e.tip}</p><p><b>${vtx('Ejemplo:','Example:')}</b> ${e.example}</p><div class="voice-syllable-chip">${e.syllables.join(' · ')}</div><div class="voice-play-row"><button class="btn primary" data-timer="${cat}:${i}">▶ ${vtx('Iniciar','Start')} ${e.duration||30}s</button><button class="btn" data-stop>■ ${vtx('Detener','Stop')}</button></div><div class="voice-status" id="status-${cat}-${i}">${vtx('Listo para comenzar.','Ready to begin.')}</div></article>`;return `<article class="voice-exercise"><h3>${e.name}</h3><div class="voice-pattern">${e.pattern.map(degreeLabel).join(' – ')}</div><p><b>${vtx('Para qué sirve:','What it does:')}</b> ${e.why}</p><p><b>${vtx('Cómo hacerlo:','How to do it:')}</b> ${e.tip}</p><p><b>${vtx('Ejemplo:','Example:')}</b> ${e.example}</p><div class="voice-controls"><label>${vtx('Sílaba','Syllable')}<select data-syllable>${e.syllables.map(s=>`<option>${s}</option>`).join('')}</select></label><label>${vtx('Nota inicial','Starting note')}<select data-start><option value="48">C3 · Do3</option><option value="50">D3 · Re3</option><option value="52">E3 · Mi3</option><option value="53">F3 · Fa3</option><option value="55">G3 · Sol3</option><option value="57">A3 · La3</option><option value="60" selected>C4 · Do4</option></select></label><label>Tempo<input data-tempo type="range" min="55" max="150" value="${e.tempo||90}"><span data-tempo-label>${e.tempo||90} BPM</span></label><label>${vtx('Repeticiones','Repetitions')}<select data-repeats><option>1</option><option selected>3</option><option>5</option><option>8</option></select></label><label>${vtx('Movimiento','Movement')}<select data-shift><option value="0">${vtx('No mover','Do not move')}</option><option value="1" selected>+½ ${vtx('tono','step')}</option><option value="-1">−½ ${vtx('tono','step')}</option></select></label></div><div class="voice-play-row"><button class="btn primary" data-play="${cat}:${i}">▶ ${vtx('Escuchar y practicar','Listen and practice')}</button><button class="btn" data-demo="${cat}:${i}">🎹 ${vtx('Solo ejemplo','Example only')}</button><button class="btn" data-stop>■ ${vtx('Detener','Stop')}</button></div><div class="voice-status" id="status-${cat}-${i}">${vtx('Listo. El piano tocará el patrón y te indicará la sílaba elegida.','Ready. The piano will play the pattern and show the selected syllable.')}</div></article>`}
function renderCategory(id,scroll=true){const c=categoryText(id),p=$('#voicePanel');if(!c||!p)return;activeVoicePanel={type:'category',id};p.classList.remove('hidden');p.innerHTML=`<span class="voice-badge">${c.icon} ${c.title}</span><h2>${c.title}</h2><p>${c.desc}</p><div class="voice-exercise-list">${(exercises[id]||[]).map((e,i)=>exerciseHtml(id,i,e)).join('')}</div>`;wireExercises();if(scroll)p.scrollIntoView({behavior:'smooth',block:'start'})}
function renderAcademyLesson(id,scroll=true){const l=academyLesson(id),p=$('#voicePanel');if(!l||!p)return;stopPlayback();rememberAcademyOpen(id);activeVoicePanel={type:'academy',id};const index=academyLessons.indexOf(l),targetLabel=l.target.type==='routine'?routineTitle(l.target.id):categoryText(l.target.id)?.title||'';p.classList.remove('hidden');p.innerHTML=`<article class="voice-academy-lesson"><div class="voice-academy-head"><span class="voice-badge">🎓 ${vtx('Clase avanzada','Advanced lesson')} ${index+1}/8</span><span class="voice-academy-duration">${l.minutes}</span></div><h2>${l.icon} ${localText(l.title)}</h2>${academyVideoHtml(id)}<section><h3>${vtx('Objetivo','Goal')}</h3><p>${localText(l.objective)}</p></section><section><h3>${vtx('Concepto clave','Key concept')}</h3><p>${localText(l.concept)}</p></section><div class="voice-academy-columns"><section><h3>${vtx('Qué escuchar o sentir','What to listen or feel for')}</h3>${academyList(l.feel)}</section><section class="academy-caution"><h3>${vtx('Qué evitar','What to avoid')}</h3>${academyList(l.avoid)}</section></div><section><h3>${vtx('Práctica guiada','Guided practice')}</h3>${academyList(l.practice)}</section>${academyInteractiveHtml(id)}<section class="academy-ministry"><h3>${vtx('Aplicación al ministerio','Ministry application')}</h3><p>${localText(l.ministry)}</p></section><section><h3>${vtx('Autoevaluación','Self-check')}</h3>${academyList(l.check)}</section><div class="voice-warning"><b>${vtx('Seguridad vocal:','Vocal safety:')}</b> ${vtx('si aparece dolor, ardor, pérdida marcada de voz o ronquera que empeora, detén la práctica.','if pain, burning, significant voice loss or worsening hoarseness appears, stop practicing.')}</div><div class="voice-play-row"><button class="btn ${academyIsComplete(id)?'academy-complete-on':'primary'}" data-academy-complete="${id}">${academyIsComplete(id)?'✓ '+vtx('Clase completada','Lesson completed'):'○ '+vtx('Marcar como completada','Mark as completed')}</button><button class="btn primary" data-academy-practice="${l.target.type}:${l.target.id}">🎹 ${vtx('Practicar en','Practice in')} ${targetLabel}</button>${index>0?`<button class="btn" data-academy-prev="${academyLessons[index-1].id}">← ${vtx('Clase anterior','Previous lesson')}</button>`:''}${index<academyLessons.length-1?`<button class="btn" data-academy-next="${academyLessons[index+1].id}">${vtx('Siguiente clase','Next lesson')} →</button>`:''}</div><p class="voice-academy-foot">${vtx('Contenido preparado con ayuda de IA y entregado como lección fija dentro de La Grey; no se genera una técnica improvisada en tiempo real.','Content prepared with AI assistance and delivered as a fixed lesson inside La Grey; vocal technique is not improvised in real time.')}</p></article>`;wireAcademyInteractive();wireAcademyVideo(id);if(scroll)p.scrollIntoView({behavior:'smooth',block:'start'})}
function wireAcademyInteractive(){$$('#voicePanel [data-ap-tempo]').forEach(r=>r.oninput=()=>{const label=r.parentElement.querySelector('[data-ap-tempo-label]');if(label)label.textContent=r.value+' BPM'})}
function wireExercises(){$$('#voicePanel [data-tempo]').forEach(r=>r.oninput=()=>r.parentElement.querySelector('[data-tempo-label]').textContent=r.value+' BPM');$$('[data-play]').forEach(b=>b.onclick=()=>playExercise(b,false));$$('[data-demo]').forEach(b=>b.onclick=()=>playExercise(b,true));$$('[data-stop]').forEach(b=>b.onclick=stopPlayback);$$('[data-timer]').forEach(b=>b.onclick=()=>startTimer(b))}
function midiFreq(m){return 440*Math.pow(2,(m-69)/12)}
function noteLabel(m){const n=NOTE_NAMES[((m%12)+12)%12],o=Math.floor(m/12)-1;return `${LATIN[n]||n}${o}`}
function audio(){if(!ctx)ctx=new (window.AudioContext||window.webkitAudioContext)();if(ctx.state==='suspended')ctx.resume();return ctx}
function pianoNote(midi,when,dur=.32){const a=audio(),gain=a.createGain(),o1=a.createOscillator(),o2=a.createOscillator();o1.type='triangle';o2.type='sine';o1.frequency.value=midiFreq(midi);o2.frequency.value=midiFreq(midi)*2;gain.gain.setValueAtTime(.0001,when);gain.gain.exponentialRampToValueAtTime(.16,when+.015);gain.gain.exponentialRampToValueAtTime(.0001,when+dur);o1.connect(gain);o2.connect(gain);gain.connect(a.destination);o1.start(when);o2.start(when);o1.stop(when+dur+.03);o2.stop(when+dur+.03)}
const wait=ms=>new Promise(r=>setTimeout(r,ms));
async function playPattern(e,root,tempo,token,status,syllable){const beat=60/tempo;let t=ctx.currentTime+.08;e.pattern.forEach(step=>{pianoNote(root+step,t,Math.max(.18,beat*.72));t+=beat});if(status)status.textContent=`🎹 ${noteLabel(root)} · ${tempo} BPM · ${vtx('canta','sing')} “${syllable}”`;await wait(e.pattern.length*beat*1000+250);return token===stopToken}
async function playAcademyInteractive(btn,demoOnly){const [lessonId,indexText]=btn.dataset[demoOnly?'academyDemo':'academyPlay'].split('|'),drill=academyInteractive[lessonId]?.[Number(indexText)],box=btn.closest('.voice-academy-drill');if(!drill||!box)return;stopPlayback();const token=++stopToken,start=Number(box.querySelector('[data-ap-start]').value),tempo=Number(box.querySelector('[data-ap-tempo]').value),reps=demoOnly?1:Number(box.querySelector('[data-ap-repeats]').value),shift=demoOnly?0:Number(box.querySelector('[data-ap-shift]').value),syllable=box.querySelector('[data-ap-syllable]').value,status=box.querySelector('[data-academy-status]');audio();for(let r=0;r<reps;r++){if(token!==stopToken)return;const root=start+(r*shift);status.textContent=`${vtx('Repetición','Repetition')} ${r+1}/${reps} · ${noteLabel(root)} · “${syllable}”`;if(!(await playPattern(drill,root,tempo,token,status,syllable)))return;if(!demoOnly){status.textContent=`🎤 ${vtx('Ahora repítelo tú con','Now repeat it with')} “${syllable}” · ${vtx('sin empujar','without pushing')}`;await wait(Math.max(1100,drill.pattern.length*(60/tempo)*720))}}status.textContent=demoOnly?vtx('✅ Ejemplo terminado.','✅ Example finished.'):vtx('✅ Serie terminada. Si siguió cómoda, puedes repetir o subir solo un semitono.','✅ Set finished. If it stayed comfortable, repeat it or move up only one semitone.')}
async function playExercise(btn,demoOnly){stopPlayback();const token=++stopToken,[cat,idx]=btn.dataset[demoOnly?'demo':'play'].split(':'),e=exercises[cat][Number(idx)],box=btn.closest('.voice-exercise'),start=Number(box.querySelector('[data-start]').value),tempo=Number(box.querySelector('[data-tempo]').value),reps=demoOnly?1:Number(box.querySelector('[data-repeats]').value),shift=demoOnly?0:Number(box.querySelector('[data-shift]').value),syllable=box.querySelector('[data-syllable]').value,status=$(`#status-${cat}-${idx}`);audio();for(let r=0;r<reps;r++){if(token!==stopToken)return;const root=start+r*shift;status.textContent=`${vtx('Repetición','Repetition')} ${r+1}/${reps} · ${noteLabel(root)} · “${syllable}”`;if(!(await playPattern(e,root,tempo,token,status,syllable)))return;if(!demoOnly){status.textContent=`🎤 ${vtx('Ahora repítelo tú con','Now repeat it with')} “${syllable}”`;await wait(Math.max(900,e.pattern.length*(60/tempo)*700));}}status.textContent=demoOnly?vtx('✅ Ejemplo terminado.','✅ Example finished.'):vtx('✅ Ejercicio terminado. Si se sintió cómodo, puedes repetirlo.','✅ Exercise finished. If it felt comfortable, you can repeat it.')}
function stopPlayback(){stopToken++;routineState=null;clearTimeout(academySceneTimer);academySceneTimer=0;$$('.voice-status').forEach(s=>{if(!s.textContent.startsWith('✅'))s.textContent=vtx('Detenido.','Stopped.')})}
function startTimer(btn){const [cat,idx]=btn.dataset.timer.split(':'),source=exercises[cat][Number(idx)],e=translatedExercise(cat,Number(idx),source),status=$(`#status-${cat}-${idx}`);stopPlayback();const token=++stopToken;let left=e.duration||30;status.textContent=`⏱️ ${left}s · ${e.example}`;const id=setInterval(()=>{if(token!==stopToken){clearInterval(id);return}left--;status.textContent=left>0?`⏱️ ${left}s · ${e.example}`:vtx('✅ Terminado. Respira normalmente.','✅ Finished. Breathe normally.');if(left<=0)clearInterval(id)},1000)}
function showRoutine(id,scroll=true){const r=routines[id],p=$('#voicePanel');if(!r||!p)return;activeVoicePanel={type:'routine',id};p.classList.remove('hidden');p.innerHTML=`<span class="voice-badge">${vtx('Rutina guiada','Guided routine')}</span><h2>${routineTitle(id)}</h2><p>${vtx('No es una lista para leer: pulsa iniciar y La Grey irá avanzando ejercicio por ejercicio.','This is not a list to read: press start and La Grey will advance exercise by exercise.')}</p><div id="routineProgress" class="routine-progress"><div class="routine-bar"><span></span></div><div id="routineStepLabel">${vtx('Preparado para comenzar.','Ready to begin.')}</div></div><div class="voice-play-row"><button class="btn primary" data-start-routine="${id}">▶ ${vtx('Iniciar rutina completa','Start full routine')}</button><button class="btn" data-routine-stop>■ ${vtx('Detener','Stop')}</button></div><div id="routineCurrent" class="routine-current">${vtx('Aquí aparecerá el ejercicio actual, la sílaba y lo que debes hacer.','The current exercise, syllable and instructions will appear here.')}</div><div class="routine-list">${r.steps.map((s,i)=>{const e=translatedExercise(s[0],s[1]);return `<div class="routine-item" data-routine-item="${i}"><b>${i+1}. ${e.name}</b><small>${e.timed?e.example:`${e.syllables[0]} · ${e.tip}`}</small></div>`}).join('')}</div>`;p.querySelector('[data-start-routine]').onclick=()=>runRoutine(id);p.querySelector('[data-routine-stop]').onclick=stopPlayback;if(scroll)p.scrollIntoView({behavior:'smooth',block:'start'})}
async function runRoutine(id){stopPlayback();audio();const token=++stopToken,r=routines[id],current=$('#routineCurrent'),label=$('#routineStepLabel'),bar=$('#routineProgress .routine-bar span');for(let i=0;i<r.steps.length;i++){if(token!==stopToken)return;$$('[data-routine-item]').forEach((x,j)=>x.classList.toggle('active',j===i));bar.style.width=((i/r.steps.length)*100)+'%';const [cat,idx,duration]=r.steps[i],e=exercises[cat][idx],te=translatedExercise(cat,idx,e);label.textContent=`${vtx('Paso','Step')} ${i+1} ${vtx('de','of')} ${r.steps.length}`;if(e.timed){current.innerHTML=`<b>${te.name}</b><br>${te.example}<br><span class="voice-syllable-chip">${e.syllables[0]}</span>`;let left=Math.min(duration,e.duration||duration);while(left>0){if(token!==stopToken)return;label.textContent=`${vtx('Paso','Step')} ${i+1}/${r.steps.length} · ${left}s`;await wait(1000);left--;}}else{const syll=e.syllables[0],tempo=e.tempo||90,start=60,reps=Math.max(2,Math.min(5,Math.round(duration/25)));current.innerHTML=`<b>${te.name}</b><br>${vtx('Canta con','Sing with')} <b>${syll}</b>. ${te.tip}<br><small>${vtx('El piano tocará y luego tendrás tiempo para repetir.','The piano will play and then you will have time to repeat.')}</small>`;for(let rep=0;rep<reps;rep++){if(token!==stopToken)return;const root=start+rep;label.textContent=`${vtx('Paso','Step')} ${i+1}/${r.steps.length} · ${vtx('repetición','repetition')} ${rep+1}/${reps} · ${noteLabel(root)}`;if(!(await playPattern(e,root,tempo,token,null,syll)))return;await wait(Math.max(900,e.pattern.length*(60/tempo)*650));}}}bar.style.width='100%';label.textContent=vtx('✅ Rutina completada','✅ Routine completed');current.innerHTML=vtx('<b>Muy bien.</b><br>La rutina terminó. Si vas a cantar ahora, mantente hidratado y evita forzar la voz.','<b>Well done.</b><br>The routine is finished. If you are going to sing now, stay hydrated and avoid forcing your voice.');$$('[data-routine-item]').forEach(x=>x.classList.remove('active'))}
function wireAcademyVideo(id){const video=$(`[data-academy-video="${id}"]`),box=$(`[data-academy-video-box="${id}"]`),actions=$(`[data-academy-video-actions="${id}"]`),eager=id==='voice-advanced-02-passaggio';if(video&&box){const showVideo=()=>{box.classList.add('has-video');actions?.classList.remove('hidden')},showFallback=()=>{box.classList.remove('has-video');actions?.classList.add('hidden')};if(eager||video.readyState>=1)showVideo();video.addEventListener('loadedmetadata',showVideo,{once:true});video.addEventListener('canplay',showVideo,{once:true});video.addEventListener('error',showFallback,{once:true});try{video.load()}catch(_){}const fullBtn=$(`[data-academy-fullscreen="${id}"]`);if(fullBtn)fullBtn.onclick=async()=>{try{if(document.fullscreenElement&&document.exitFullscreen){await document.exitFullscreen();return}if(video.requestFullscreen){await video.requestFullscreen();return}if(video.webkitEnterFullscreen){video.webkitEnterFullscreen();return}if(video.webkitRequestFullscreen){video.webkitRequestFullscreen();return}}catch(error){console.warn('[La Grey Academia] No se pudo activar pantalla completa',error)}}}renderAcademyStory(id,0)}
function renderAcademyStory(id,index){const v=academyVideos[id],box=$(`[data-academy-story-box="${id}"]`);if(!v||!box)return;const scenes=v.scenes||[],safe=Math.max(0,Math.min(scenes.length-1,index));box.dataset.scene=String(safe);const scene=box.querySelector('[data-academy-story-scene]'),count=box.querySelector('[data-academy-story-count]'),bar=box.querySelector('[data-academy-story-progress]');if(scene)scene.textContent=localText(scenes[safe]);if(count)count.textContent=`${vtx('Escena','Scene')} ${safe+1}/${scenes.length}`;if(bar)bar.style.width=((safe+1)/scenes.length*100)+'%'}
function openAcademyStory(id){const box=$(`[data-academy-story-box="${id}"]`);if(!box)return;box.classList.remove('hidden');renderAcademyStory(id,Number(box.dataset.scene||0));box.scrollIntoView({behavior:'smooth',block:'nearest'})}
function moveAcademyStory(id,delta){clearTimeout(academySceneTimer);const v=academyVideos[id],box=$(`[data-academy-story-box="${id}"]`);if(!v||!box)return;renderAcademyStory(id,Math.max(0,Math.min(v.scenes.length-1,Number(box.dataset.scene||0)+delta)))}
function playAcademyStory(id){clearTimeout(academySceneTimer);openAcademyStory(id);const v=academyVideos[id],box=$(`[data-academy-story-box="${id}"]`);if(!v||!box)return;const step=()=>{const i=Number(box.dataset.scene||0);if(i>=v.scenes.length-1){academySceneTimer=0;return}renderAcademyStory(id,i+1);academySceneTimer=setTimeout(step,3200)};academySceneTimer=setTimeout(step,3200)}
function refreshVoiceLanguage(){translateVoiceShell();if(!activeVoicePanel)return;stopPlayback();if(activeVoicePanel.type==='category')renderCategory(activeVoicePanel.id,false);else if(activeVoicePanel.type==='routine')showRoutine(activeVoicePanel.id,false);else if(activeVoicePanel.type==='academy')renderAcademyLesson(activeVoicePanel.id,false)}
function onCapture(ev){const voice=ev.target.closest('[data-open="voice"]');if(voice){ev.preventDefault();ev.stopPropagation();showVoice();return}const back=ev.target.closest('[data-voice-home]');if(back){ev.preventDefault();ev.stopPropagation();goHome();return}const cat=ev.target.closest('[data-voice-cat]');if(cat){ev.preventDefault();renderCategory(cat.dataset.voiceCat);return}const routine=ev.target.closest('[data-routine]');if(routine){ev.preventDefault();showRoutine(routine.dataset.routine);return}const lesson=ev.target.closest('[data-academy-lesson]');if(lesson){ev.preventDefault();renderAcademyLesson(lesson.dataset.academyLesson);return}const complete=ev.target.closest('[data-academy-complete]');if(complete){ev.preventDefault();toggleAcademyComplete(complete.dataset.academyComplete);return}const ap=ev.target.closest('[data-academy-play]');if(ap){ev.preventDefault();playAcademyInteractive(ap,false);return}const ad=ev.target.closest('[data-academy-demo]');if(ad){ev.preventDefault();playAcademyInteractive(ad,true);return}const astop=ev.target.closest('[data-academy-stop]');if(astop){ev.preventDefault();stopPlayback();return}const story=ev.target.closest('[data-academy-story]');if(story){ev.preventDefault();openAcademyStory(story.dataset.academyStory);return}const sp=ev.target.closest('[data-story-play]');if(sp){ev.preventDefault();playAcademyStory(sp.dataset.storyPlay);return}const sprev=ev.target.closest('[data-story-prev]');if(sprev){ev.preventDefault();moveAcademyStory(sprev.dataset.storyPrev,-1);return}const snext=ev.target.closest('[data-story-next]');if(snext){ev.preventDefault();moveAcademyStory(snext.dataset.storyNext,1);return}const prev=ev.target.closest('[data-academy-prev]');if(prev){ev.preventDefault();renderAcademyLesson(prev.dataset.academyPrev);return}const next=ev.target.closest('[data-academy-next]');if(next){ev.preventDefault();renderAcademyLesson(next.dataset.academyNext);return}const practice=ev.target.closest('[data-academy-practice]');if(practice){ev.preventDefault();const [type,id]=practice.dataset.academyPractice.split(':');if(type==='routine')showRoutine(id);else renderCategory(id);return}if(!$('#voiceView')?.classList.contains('hidden')&&ev.target.closest('nav button,[data-home],[data-nav]'))stopPlayback()}
